/**
 * Navigation - Navigation interface attached to physics bodies.
 */
export class Navigation {
    /**
     * Create a navigation interface for a body.
     *
     * @param {Object} body - The physics body (KinematicBody or DynamicBody).
     */
    constructor(body: any);
    /**
     * Reference to the physics body.
     * @type {Object}
     * @private
     */
    private _body;
    /**
     * Reference to the navigation grid (null for BASIC mode).
     * @type {PathfindingGrid|null}
     * @private
     */
    private _grid;
    /**
     * Navigation type (BASIC, ASTAR, NAVMESH).
     * @type {string}
     * @private
     */
    private _type;
    /**
     * Whether navigation is enabled.
     * @type {boolean}
     * @private
     */
    private _enabled;
    /**
     * Navigation configuration.
     * @type {Object}
     * @private
     */
    private _config;
    /**
     * Current destination.
     * @type {THREE.Vector3|null}
     * @private
     */
    private _destination;
    /**
     * Navigation version for invalidating stale paths.
     * @type {number}
     * @private
     */
    private _navigationVersion;
    /**
     * Poll interval for checking arrival.
     * @type {number|null}
     * @private
     */
    private _pollInterval;
    /**
     * Promise resolve function for current navigation.
     * @type {Function|null}
     * @private
     */
    private _navigationResolve;
    /**
     * Enable navigation for this body.
     *
     * @param {PathfindingGrid|null} [grid=null] - Grid for A* navigation (null for BASIC).
     * @param {Object} [config={}] - Navigation configuration.
     * @param {string} [config.type] - Navigation type (auto-detected if not specified).
     * @param {number} [config.maxSpeed=5.0] - Maximum movement speed.
     * @param {number} [config.arrivalRadius=1.5] - Distance to consider arrived.
     * @param {number} [config.avoidanceRadius=1.5] - Obstacle avoidance radius.
     * @param {number} [config.rotationSpeed=0.15] - Rotation interpolation speed.
     * @param {number} [config.replanThreshold=5.0] - Time blocked before replanning.
     * @returns {Promise<Navigation>} This instance for chaining.
     */
    enable(grid?: PathfindingGrid | null, config?: {
        type?: string;
        maxSpeed?: number;
        arrivalRadius?: number;
        avoidanceRadius?: number;
        rotationSpeed?: number;
        replanThreshold?: number;
    }): Promise<Navigation>;
    /**
     * Navigate to a destination.
     * Auto-enables BASIC navigation if not already enabled.
     *
     * @param {THREE.Vector3|{x: number, y: number, z: number}} destination - Target position.
     * @param {Function} [onArrived] - Optional callback when arrived.
     * @returns {Promise<boolean>} Resolves true on arrival, false on path failure.
     */
    navigateTo(destination: THREE.Vector3 | {
        x: number;
        y: number;
        z: number;
    }, onArrived?: Function): Promise<boolean>;
    /**
     * Stop current navigation.
     */
    stop(): void;
    /**
     * Disable navigation and clean up.
     */
    disable(): void;
    /**
     * Cancel navigation without stopping in worker.
     *
     * @private
     */
    private _cancelNavigation;
    /**
     * Complete navigation with result.
     *
     * @param {boolean} success - Whether navigation succeeded.
     * @param {Function|null} callback - Optional arrival callback.
     * @private
     */
    private _completeNavigation;
    /**
     * Update navigation configuration.
     *
     * @param {Object} config - Configuration options.
     * @returns {Navigation} This instance for chaining.
     */
    set(config: any): Navigation;
    /**
     * Whether navigation is enabled for this body.
     * @type {boolean}
     * @readonly
     */
    readonly get enabled(): boolean;
    /**
     * The navigation type (BASIC, ASTAR, NAVMESH).
     * @type {string}
     * @readonly
     */
    readonly get type(): string;
    /**
     * Whether the body is currently navigating.
     * @type {boolean}
     * @readonly
     */
    readonly get isNavigating(): boolean;
    /**
     * Whether the body has arrived at destination.
     * Returns true only immediately after arrival, then resets.
     * @type {boolean}
     * @readonly
     */
    readonly get hasArrived(): boolean;
    /**
     * Current destination (if navigating).
     * @type {THREE.Vector3|null}
     * @readonly
     */
    readonly get destination(): THREE.Vector3 | null;
    /**
     * The PathfindingGrid being used (null for BASIC mode).
     * @type {PathfindingGrid|null}
     * @readonly
     */
    readonly get grid(): PathfindingGrid | null;
    /**
     * Current configuration.
     * @type {Object}
     * @readonly
     */
    readonly get config(): any;
}
